const numb beta2 = numb(0.28867513459481287) + numb(1.6725140369678172e-17);
const numb beta3 = numb(0.23570226039551584) + numb(2.3915615546644207e-18);
const numb third = numb(1) / numb(3);
const ucmplx row2[] = {ucmplx(numb(0.5), -beta2), ucmplx(numb(0.5), beta2)};
const ucmplx row3[] = {ucmplx(third, -beta3), ucmplx(third, numb(0)), ucmplx(third, beta3)};

auto cd = [&](ucmplx* z, const ucmplx& fraction) {
    const ucmplx t = fraction * (h * numb(0.5));
    ucmplx& theta = z[0];
    ucmplx& omega = z[1];
    theta = theta + t * omega;
    omega = omega - t * sin(theta);
    omega = omega - t * sin(theta);
    theta = theta + t * omega;
};

ucmplx y2[2], y3[2];
for (int i = 0; i < 2; ++i) {
    y2[i] = ucmplx(X[i], numb(0));
    y3[i] = y2[i];
}
for (const auto& c : row2) cd(y2, c);
for (const auto& c : row3) cd(y3, c);
const numb w2 = -numb(1) / numb(5);
const numb w3 = numb(6) / numb(5);
for (int i = 0; i < 2; ++i) X[i] = w2 * y2[i].re + w3 * y3[i].re;
